window.receiveProjectSource({"path": "test/unit/microservices/web_extraction/test_layer_two_classification.py", "lines": ["\"\"\"Unit tests for the L2 classification policy chain (DAT-6369).", "", "Focused on the **time-window demote** introduced when the date filter", "moved out of ``deduplicate_article`` (the SQL prefilter) into a", "post-aggregation step in ``classify_layer_two_article``, and on the", "``rejected_match_info`` channel that carries a verifier adjudication onto a", "UNIQUE outcome's row. The remaining links of the classification chain (cutoff freeze, dedup, verifier,", "retry-canonical demote, group resolution) have their own dedicated tests", "elsewhere; here we stub them and verify only the demote's contract.", "", "Stubs in this file:", "", "- ``deduplicate_article``  \u2192 returns a controlled ``DeduplicationResult``", "- ``ensure_layer_two_retry_similarity_cutoff`` \u2192 no-op passthrough", "- ``maybe_verify_borderline`` \u2192 no-op passthrough (no LLM call)", "- ``resolve_retry_syndication_group_id`` \u2192 returns ``None``", "- ``_load_matched_article_published_at`` \u2192 returns a controlled datetime", "\"\"\"", "", "import json", "from datetime import datetime, timedelta, timezone", "from unittest.mock import AsyncMock, MagicMock, patch", "from uuid import uuid4", "", "import pytest", "", "from common.llm_catalog import OPENAI_PROVIDER", "from common.services.llm_model_usability import llm_model_provider", "from microservices.web_extraction.models import ArticleChunk", "from microservices.web_extraction.schemas import ArticleSchema", "from microservices.web_extraction.schemas.article_base_schemas import (", "    ArticleItem,", "    RawAPIResponse,", ")", "from microservices.web_extraction.schemas.embedding import ChunkEmbedding, ChunkVectors", "from microservices.web_extraction.services.helpers import borderline_verifier", "from microservices.web_extraction.services.helpers import (", "    layer_two_classification as layer_two_classification_module,", ")", "from microservices.web_extraction.services.helpers.layer_two import (", "    CandidateMatch,", "    DeduplicationClassification,", "    DeduplicationResult,", ")", "from microservices.web_extraction.services.helpers.layer_two_classification import (", "    LayerTwoRetryContext,", "    classify_layer_two_article,", ")", "from test.unit._doubles import APIHelperDouble", "", "pytestmark = pytest.mark.unit", "", "", "# ---------------------------------------------------------------------------", "# Test fixtures + helpers", "# ---------------------------------------------------------------------------", "", "", "_INCOMING_DATE = datetime(2026, 4, 10, 12, 0, tzinfo=timezone.utc)", "", "", "def _make_article(", "    *,", "    date_published=_INCOMING_DATE,", "    url=\"https://example.com/incoming\",", "    headline=\"Incoming headline\",", ") -> ArticleSchema:", "    \"\"\"Build a minimal ArticleSchema suitable for the helper's reads.\"\"\"", "    return ArticleSchema(", "        source=\"ZYTE\",", "        raw_response=RawAPIResponse(", "            status_code=200,", "            headers={},", "            source=\"ZYTE\",", "            body={\"dummy\": \"body\"},", "        ),", "        article_data=ArticleItem(", "            url=url,", "            headline=headline,", "            content=\"Incoming article body content.\",", "            date_published=date_published,", "        ),", "        article_url=url,", "    )", "", "", "def _make_chunk_vectors() -> ChunkVectors:", "    return ChunkVectors(", "        chunks=[", "            ChunkEmbedding(", "                chunk_index=0,", "                chunk_text=\"incoming chunk\",", "                token_count=8,", "                embedding=[0.1] * 3072,", "            )", "        ]", "    )", "", "", "def _make_best_match_chunk(article_id) -> ArticleChunk:", "    chunk = MagicMock(spec=ArticleChunk)", "    chunk.article_id = article_id", "    return chunk", "", "", "def _dedup_result(", "    *,", "    classification: DeduplicationClassification,", "    article_score: float = 0.85,", "    matched_article_id=None,", ") -> DeduplicationResult:", "    if classification == DeduplicationClassification.UNIQUE:", "        best_match = None", "    else:", "        best_match = _make_best_match_chunk(matched_article_id or uuid4())", "    return DeduplicationResult(", "        classification=classification,", "        best_match=best_match,", "        article_score=article_score,", "        match_info={\"matched_chunk_index\": 0},", "    )", "", "", "def _candidate(article_id, *, best_similarity: float = 0.9) -> CandidateMatch:", "    \"\"\"Build a CandidateMatch whose ``best_chunk`` carries ``article_id``.\"\"\"", "    return CandidateMatch(", "        article_id=article_id,", "        best_similarity=best_similarity,", "        best_chunk=_make_best_match_chunk(article_id),", "    )", "", "", "def _unique_with_candidates(candidates) -> DeduplicationResult:", "    \"\"\"A UNIQUE dedup result carrying ANN candidates for the blocking-key step.\"\"\"", "    return DeduplicationResult(", "        classification=DeduplicationClassification.UNIQUE,", "        best_match=None,", "        article_score=0.55,  # diluted, out of every verifier band", "        match_info={},", "        candidates=list(candidates),", "    )", "", "", "def _syndication_signal_result(", "    article_id,", "    *,", "    article_score: float = 0.38,", "    matched_article_score=None,", ") -> DeduplicationResult:", "    \"\"\"A dedup result the absolute-count syndication signal already promoted.", "", "    Mirrors what ``deduplicate_article`` returns when the signal rescues a", "    diluted UNIQUE: SYNDICATION_CANDIDATE with ``article_score`` left on the", "    top-scored candidate and the signal payload recorded in ``match_info``. Pass", "    ``matched_article_score`` to model a retarget, where the matched candidate", "    scores lower than the top one.", "    \"\"\"", "    matched = article_score if matched_article_score is None else matched_article_score", "    return DeduplicationResult(", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        best_match=_make_best_match_chunk(article_id),", "        article_score=article_score,", "        match_info={", "            \"matched_chunk_index\": 0,", "            \"syndication_signal\": {", "                \"matched_article_id\": str(article_id),", "                \"high_sim_matched_chunks\": 2,", "                \"similarity_threshold\": 0.92,", "                \"matched_article_score\": matched,", "                \"top_candidate_article_score\": article_score,", "            },", "        },", "        candidates=[_candidate(article_id)],", "        matched_article_score=matched,", "    )", "", "", "# A verbatim news-style headline with enough words to clear the specificity bar.", "_VERBATIM_HEADLINE = \"Regional water authority approves new desalination plant funding\"", "", "", "@pytest.fixture", "def _stub_chain(monkeypatch):", "    \"\"\"Stub everything around the demote so the test focuses on its logic.", "", "    Returns a small accessor with knobs to set the dedup result and the", "    matched-article published_at. Tests configure those, then call", "    ``classify_layer_two_article``; the fixture handles the rest.", "    \"\"\"", "    state = {", "        \"dedup_result\": None,", "        \"matched_published_at\": None,", "        \"config_window_days\": 7,", "        # article_id -> (title, url) returned by the batched title lookup.", "        \"titles_by_article\": {},", "        # Recorded verifier invocations + optional override of its return value.", "        \"verifier_calls\": [],", "        \"verifier_impl\": None,", "        # Recorded group-resolution invocations (to assert best_match_article_id).", "        \"resolve_group_calls\": [],", "    }", "", "    async def _stub_ensure_cutoff(*args, **kwargs):", "        return None", "", "    async def _stub_dedup(*args, **kwargs):", "        return state[\"dedup_result\"]", "", "    async def _stub_verifier(*args, **kwargs):", "        state[\"verifier_calls\"].append(kwargs)", "        impl = state[\"verifier_impl\"]", "        if impl is not None:", "            return impl(kwargs)", "        # No-op passthrough: classification stays the same, no addendum.", "        return kwargs[\"classification\"], None", "", "    async def _stub_load_matched_date(*args, **kwargs):", "        return state[\"matched_published_at\"]", "", "    async def _stub_load_titles(db, article_ids):", "        return state[\"titles_by_article\"]", "", "    async def _stub_resolve_group(*args, **kwargs):", "        state[\"resolve_group_calls\"].append(kwargs)", "        return None", "", "    monkeypatch.setattr(", "        \"microservices.web_extraction.services.helpers.layer_two_classification.\"", "        \"ensure_layer_two_retry_similarity_cutoff\",", "        _stub_ensure_cutoff,", "    )", "    monkeypatch.setattr(", "        \"microservices.web_extraction.services.helpers.layer_two_classification.\"", "        \"deduplicate_article\",", "        _stub_dedup,", "    )", "    monkeypatch.setattr(", "        \"microservices.web_extraction.services.helpers.layer_two_classification.\"", "        \"maybe_verify_borderline\",", "        _stub_verifier,", "    )", "    monkeypatch.setattr(", "        \"microservices.web_extraction.services.helpers.layer_two_classification.\"", "        \"_load_matched_article_published_at\",", "        _stub_load_matched_date,", "    )", "    monkeypatch.setattr(", "        \"microservices.web_extraction.services.helpers.layer_two_classification.\"", "        \"_load_earliest_titles_by_article\",", "        _stub_load_titles,", "    )", "    monkeypatch.setattr(", "        \"microservices.web_extraction.services.helpers.layer_two_classification.\"", "        \"resolve_retry_syndication_group_id\",", "        _stub_resolve_group,", "    )", "", "    # Patch ``webex_config.DEDUP_TIME_WINDOW_DAYS`` so each test controls it", "    # without env vars. Patching a single attribute (not the whole module)", "    # keeps the rest of the config intact for unrelated reads.", "    with patch(", "        \"microservices.web_extraction.services.helpers.layer_two_classification.webex_config\"", "    ) as mock_config:", "        mock_config.DEDUP_TIME_WINDOW_DAYS = state[\"config_window_days\"]", "        # Verifier lede slice still happens \u2014 give it a real int.", "        mock_config.VERIFIER_LEDE_CHARS = 1200", "        # Title/headline blocking key defaults (ships enabled, 5-word floor).", "        mock_config.DEDUP_TITLE_BLOCKING_ENABLED = True", "        mock_config.DEDUP_TITLE_BLOCKING_MIN_WORDS = 5", "        state[\"config\"] = mock_config", "", "        def _set_window_days(days: int) -> None:", "            mock_config.DEDUP_TIME_WINDOW_DAYS = days", "", "        state[\"set_window_days\"] = _set_window_days", "        yield state", "", "", "async def _run(state, **call_kwargs):", "    \"\"\"Invoke classify_layer_two_article with stubbed deps and the test's article.\"\"\"", "    return await classify_layer_two_article(", "        AsyncMock(),  # db \u2014 stubs intercept all DB reads", "        AsyncMock(),  # api_helper \u2014 stub verifier intercepts the LLM call", "        **{\"api_key\": \"sk-test\", **call_kwargs},", "    )", "", "", "def _retry_context_first_attempt() -> LayerTwoRetryContext:", "    return LayerTwoRetryContext.first_attempt()", "", "", "# ---------------------------------------------------------------------------", "# Time-window demote tests", "# ---------------------------------------------------------------------------", "", "", "@pytest.mark.parametrize(", "    \"matched_offset_days\",", "    [", "        # Matched older than incoming (common case: wire-service archive", "        # republish, late crawl of a stale story).", "        -10,", "        # Matched newer than incoming (less common but real: incoming was", "        # crawled from a stale feed snapshot, or matched is a future-dated", "        # embargoed release). The demote uses ``abs(delta) > window`` so it", "        # must fire symmetrically; without this case a refactor that drops", "        # ``abs()`` would still pass the older-side test.", "        +10,", "    ],", "    ids=[\"matched_older_than_incoming\", \"matched_newer_than_incoming\"],", ")", "async def test_demote_fires_when_matched_is_outside_window(_stub_chain, matched_offset_days):", "    \"\"\"SYNDICATION_CANDIDATE + matched article > N days from incoming \u2192 UNIQUE.", "", "    The boilerplate-defense case: a syndication-zone score whose match", "    sits outside the time window is treated as a fresh canonical, not a", "    group member. Locks in the lineage clearing too (UNIQUE invariant),", "    and the symmetry of the ``abs()`` window \u2014 outside in either", "    direction triggers the demote.", "    \"\"\"", "    matched_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _dedup_result(", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        article_score=0.85,", "        matched_article_id=matched_id,", "    )", "    _stub_chain[\"matched_published_at\"] = _INCOMING_DATE + timedelta(days=matched_offset_days)", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    # Matched-lineage fields must be cleared so the plan's shape matches the", "    # declared classification \u2014 orchestrator gates on these for the UNIQUE", "    # write, and a future caller reading the plan directly should not see", "    # stale dedup/verifier state on what is now a UNIQUE article.", "    assert plan.best_match is None", "    assert plan.match_info == {}", "    # A score-based demote keeps the dedup-produced score rather than zeroing", "    # it, so audit consumers can correlate the plan with the demote log line.", "    # The orchestrator only logs it when best_match is set, so this leak is", "    # invisible downstream. (Contrast the None a headline-blocking promotion", "    # persists \u2014 that match is score-independent.)", "    assert plan.similarity_score == 0.85", "", "", "async def test_demote_skipped_when_matched_is_inside_window(_stub_chain):", "    \"\"\"SYNDICATION_CANDIDATE + matched within \u00b1N days \u2192 stays SYNDICATION_CANDIDATE.\"\"\"", "    matched_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _dedup_result(", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        matched_article_id=matched_id,", "    )", "    _stub_chain[\"matched_published_at\"] = _INCOMING_DATE - timedelta(days=3)", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert plan.best_match is not None", "    assert plan.best_match.article_id == matched_id", "", "", "async def test_window_boundary_inclusive(_stub_chain):", "    \"\"\"A match exactly ``DEDUP_TIME_WINDOW_DAYS`` away from the incoming date", "    stays inside the window \u2014 the comparison uses ``> window``, not ``>=``.", "    Locks in that the boundary is inclusive of the configured day count.", "    \"\"\"", "    matched_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _dedup_result(", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        matched_article_id=matched_id,", "    )", "    _stub_chain[\"matched_published_at\"] = _INCOMING_DATE - timedelta(days=7)", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.SYNDICATION_CANDIDATE", "", "", "async def test_duplicate_is_exempt_from_demote(_stub_chain):", "    \"\"\"DUPLICATE matches stay DUPLICATE regardless of how old the match is.", "    The whole point of moving the date filter out of dedup was to stop", "    high-confidence content matches from being dropped on date alone.", "    \"\"\"", "    matched_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _dedup_result(", "        classification=DeduplicationClassification.DUPLICATE,", "        article_score=0.97,", "        matched_article_id=matched_id,", "    )", "    _stub_chain[\"matched_published_at\"] = _INCOMING_DATE - timedelta(days=365)", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.DUPLICATE", "    assert plan.best_match is not None", "", "", "async def test_demote_skipped_when_matched_has_no_published_date(_stub_chain):", "    \"\"\"If the matched article's ``zyte_articles.date_published`` is NULL,", "    we can't compute time difference \u2014 fall back to trusting the dedup", "    score. This avoids demoting on missing data.", "    \"\"\"", "    matched_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _dedup_result(", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        matched_article_id=matched_id,", "    )", "    _stub_chain[\"matched_published_at\"] = None  # no zyte date available", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.SYNDICATION_CANDIDATE", "", "", "async def test_demote_skipped_when_incoming_has_no_published_date(_stub_chain):", "    \"\"\"If the incoming article has no resolvable ``date_published``, we", "    can't compute the window \u2014 skip the demote. Matches the symmetry of", "    the matched-article-missing-date case above.", "    \"\"\"", "    matched_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _dedup_result(", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        matched_article_id=matched_id,", "    )", "    _stub_chain[\"matched_published_at\"] = _INCOMING_DATE - timedelta(days=30)", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(date_published=None),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.SYNDICATION_CANDIDATE", "", "", "async def test_demote_disabled_when_window_days_is_zero(_stub_chain):", "    \"\"\"``DEDUP_TIME_WINDOW_DAYS == 0`` is the kill switch: even with a", "    far-out-of-window match, the demote must not fire.", "    \"\"\"", "    _stub_chain[\"set_window_days\"](0)", "", "    matched_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _dedup_result(", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        matched_article_id=matched_id,", "    )", "    _stub_chain[\"matched_published_at\"] = _INCOMING_DATE - timedelta(days=365)", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.SYNDICATION_CANDIDATE", "", "", "# ---------------------------------------------------------------------------", "# Title/headline blocking-key tests", "# ---------------------------------------------------------------------------", "", "", "async def test_title_blocking_promotes_cross_publisher_verbatim_headline(_stub_chain):", "    \"\"\"UNIQUE + verbatim cross-publisher headline on an ANN candidate \u2192 promoted.", "", "    Locks in the whole promotion contract: SYNDICATION_CANDIDATE, best_match set", "    to the candidate's chunk, best_match_article_id propagated to BOTH the", "    verifier gate and group resolution (Codex F4), and match_info carrying the", "    ``verifier_forced`` hook (Codex F3).", "    \"\"\"", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _unique_with_candidates([_candidate(cand_id)])", "    _stub_chain[\"titles_by_article\"] = {cand_id: (_VERBATIM_HEADLINE, \"https://otherwire.com/x\")}", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(headline=_VERBATIM_HEADLINE, url=\"https://example.com/incoming\"),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert plan.best_match is not None", "    assert plan.best_match.article_id == cand_id", "    tbk = plan.match_info[\"title_blocking_key\"]", "    assert tbk[\"verifier_forced\"] is True", "    assert tbk[\"matched_article_id\"] == str(cand_id)", "", "    # The promoted candidate id must reach the verifier gate and group resolver.", "    assert _stub_chain[\"verifier_calls\"][0][\"matched_article_id\"] == cand_id", "    assert _stub_chain[\"verifier_calls\"][0][\"verifier_forced\"] is True", "    assert _stub_chain[\"resolve_group_calls\"][0][\"best_match_article_id\"] == cand_id", "", "", "async def test_title_blocking_verifier_rejection_demotes_to_unique(_stub_chain):", "    \"\"\"Forced promotion + verifier says 'different' \u2192 demote to UNIQUE, clear lineage.\"\"\"", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _unique_with_candidates([_candidate(cand_id)])", "    _stub_chain[\"titles_by_article\"] = {cand_id: (_VERBATIM_HEADLINE, \"https://otherwire.com/x\")}", "    _stub_chain[\"verifier_impl\"] = lambda kw: (", "        DeduplicationClassification.UNIQUE,", "        {\"llm_verdict\": {\"event\": \"different\"}, \"llm_band\": \"syndication_unique\"},", "    )", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(headline=_VERBATIM_HEADLINE),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.best_match is None", "    assert plan.match_info == {}", "    # Lineage cleared before group resolution.", "    assert _stub_chain[\"resolve_group_calls\"][0][\"best_match_article_id\"] is None", "", "", "async def test_title_blocking_verifier_failure_biases_unique(_stub_chain):", "    \"\"\"Forced promotion + verifier failure (llm_failed) \u2192 biased to UNIQUE, cleared.\"\"\"", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _unique_with_candidates([_candidate(cand_id)])", "    _stub_chain[\"titles_by_article\"] = {cand_id: (_VERBATIM_HEADLINE, \"https://otherwire.com/x\")}", "    _stub_chain[\"verifier_impl\"] = lambda kw: (", "        DeduplicationClassification.UNIQUE,", "        {\"llm_failed\": True, \"llm_band\": \"syndication_unique\"},", "    )", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(headline=_VERBATIM_HEADLINE),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.best_match is None", "    assert plan.match_info == {}", "", "", "async def test_title_blocking_verifier_confirmation_keeps_promotion(_stub_chain):", "    \"\"\"Forced promotion + verifier confirms 'same' \u2192 stays SYNDICATION_CANDIDATE,", "    verifier addendum merged alongside the blocking-key match_info.", "    \"\"\"", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _unique_with_candidates([_candidate(cand_id)])", "    _stub_chain[\"titles_by_article\"] = {cand_id: (_VERBATIM_HEADLINE, \"https://otherwire.com/x\")}", "    _stub_chain[\"verifier_impl\"] = lambda kw: (", "        DeduplicationClassification.SYNDICATION_CANDIDATE,", "        {\"llm_verdict\": {\"event\": \"same\"}, \"llm_band\": \"syndication_unique\"},", "    )", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(headline=_VERBATIM_HEADLINE),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert plan.best_match is not None", "    assert plan.match_info[\"title_blocking_key\"][\"verifier_forced\"] is True", "    assert plan.match_info[\"llm_verdict\"] == {\"event\": \"same\"}", "", "", "async def test_title_blocking_same_publisher_not_promoted(_stub_chain):", "    \"\"\"Identical headline but SAME publisher \u2192 not a syndication; stays UNIQUE.\"\"\"", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _unique_with_candidates([_candidate(cand_id)])", "    _stub_chain[\"titles_by_article\"] = {cand_id: (_VERBATIM_HEADLINE, \"https://example.com/other\")}", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(headline=_VERBATIM_HEADLINE, url=\"https://example.com/incoming\"),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.best_match is None", "    assert \"title_blocking_key\" not in plan.match_info", "    assert _stub_chain[\"verifier_calls\"] == []", "", "", "async def test_title_blocking_subdomain_same_publisher_not_promoted(_stub_chain):", "    \"\"\"Bare domain vs its subdomain is the SAME publisher \u2192 not promoted.", "", "    ``parse_publisher_hostname`` only strips ``www.``/``m.``, so ``example.com`` and", "    ``news.example.com`` would otherwise read as cross-publisher; the", "    registrable-domain comparison in ``same_publisher`` keeps this pair UNIQUE.", "    \"\"\"", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _unique_with_candidates([_candidate(cand_id)])", "    _stub_chain[\"titles_by_article\"] = {", "        cand_id: (_VERBATIM_HEADLINE, \"https://news.example.com/other\")", "    }", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(headline=_VERBATIM_HEADLINE, url=\"https://example.com/incoming\"),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.best_match is None", "    assert \"title_blocking_key\" not in plan.match_info", "    assert _stub_chain[\"verifier_calls\"] == []", "", "", "async def test_title_blocking_sibling_subdomains_same_publisher_not_promoted(_stub_chain):", "    \"\"\"Sibling subdomains of one publisher network are the SAME publisher.", "", "    Neither ``news.example.com`` nor ``sports.example.com`` is an ancestor of the", "    other, so an ancestor-only check would read them as cross-publisher and", "    force-group a publisher's own re-run of a story.", "    \"\"\"", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _unique_with_candidates([_candidate(cand_id)])", "    _stub_chain[\"titles_by_article\"] = {", "        cand_id: (_VERBATIM_HEADLINE, \"https://sports.example.com/other\")", "    }", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(headline=_VERBATIM_HEADLINE, url=\"https://news.example.com/incoming\"),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.best_match is None", "    assert \"title_blocking_key\" not in plan.match_info", "    assert _stub_chain[\"verifier_calls\"] == []", "", "", "async def test_title_blocking_two_label_suffix_publishers_still_cross_publisher(_stub_chain):", "    \"\"\"Two distinct ``.co.uk`` publishers must still promote.", "", "    Guards the recall side of the registrable-domain reduction: taking only the", "    last two labels would collapse both hosts to ``co.uk`` and suppress every", "    UK-to-UK syndication.", "    \"\"\"", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _unique_with_candidates([_candidate(cand_id)])", "    _stub_chain[\"titles_by_article\"] = {", "        cand_id: (_VERBATIM_HEADLINE, \"https://theguardian.co.uk/other\")", "    }", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(headline=_VERBATIM_HEADLINE, url=\"https://bbc.co.uk/incoming\"),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert plan.best_match is not None", "    assert plan.match_info[\"title_blocking_key\"][\"matched_article_id\"] == str(cand_id)", "", "", "@pytest.mark.parametrize(", "    (\"host\", \"expected\"),", "    [", "        (\"example.com\", \"example.com\"),", "        (\"news.example.com\", \"example.com\"),", "        (\"a.b.c.example.com\", \"example.com\"),", "        (\"bbc.co.uk\", \"bbc.co.uk\"),", "        (\"news.bbc.co.uk\", \"bbc.co.uk\"),", "        (\"abc.net.au\", \"abc.net.au\"),", "        (\"co.uk\", \"co.uk\"),", "        (\"localhost\", \"localhost\"),", "        (\"News.Example.COM\", \"example.com\"),", "    ],", ")", "def test_registrable_domain_reduction(host, expected):", "    \"\"\"eTLD+1 reduction: two-label public suffixes keep a third label, others don't.\"\"\"", "    from microservices.web_extraction.services.helpers.borderline_verifier import (", "        registrable_domain,", "    )", "", "    assert registrable_domain(host) == expected", "", "", "async def test_title_blocking_short_masthead_not_promoted(_stub_chain):", "    \"\"\"A short recurring masthead below the specificity bar \u2192 not promoted.\"\"\"", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _unique_with_candidates([_candidate(cand_id)])", "    _stub_chain[\"titles_by_article\"] = {cand_id: (\"Morning Briefing\", \"https://otherwire.com/x\")}", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(headline=\"Morning Briefing\", url=\"https://example.com/incoming\"),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.best_match is None", "", "", "async def test_title_blocking_deterministic_winner_highest_similarity(_stub_chain):", "    \"\"\"Multiple equal-title cross-publisher candidates \u2192 highest best_similarity wins.\"\"\"", "    cand_lo = uuid4()", "    cand_hi = uuid4()", "    _stub_chain[\"dedup_result\"] = _unique_with_candidates(", "        [", "            _candidate(cand_lo, best_similarity=0.90),", "            _candidate(cand_hi, best_similarity=0.97),", "        ]", "    )", "    _stub_chain[\"titles_by_article\"] = {", "        cand_lo: (_VERBATIM_HEADLINE, \"https://pub-a.com/x\"),", "        cand_hi: (_VERBATIM_HEADLINE, \"https://pub-b.com/y\"),", "    }", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(headline=_VERBATIM_HEADLINE, url=\"https://example.com/incoming\"),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert plan.best_match.article_id == cand_hi", "", "", "async def test_title_blocking_deterministic_winner_tiebreak_smallest_uuid(_stub_chain):", "    \"\"\"Equal similarity \u2192 smallest article_id UUID breaks the tie.\"\"\"", "    id_a = uuid4()", "    id_b = uuid4()", "    smaller = min(id_a, id_b, key=lambda u: u.int)", "    _stub_chain[\"dedup_result\"] = _unique_with_candidates(", "        [", "            _candidate(id_a, best_similarity=0.93),", "            _candidate(id_b, best_similarity=0.93),", "        ]", "    )", "    _stub_chain[\"titles_by_article\"] = {", "        id_a: (_VERBATIM_HEADLINE, \"https://pub-a.com/x\"),", "        id_b: (_VERBATIM_HEADLINE, \"https://pub-b.com/y\"),", "    }", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(headline=_VERBATIM_HEADLINE, url=\"https://example.com/incoming\"),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.best_match.article_id == smaller", "", "", "async def test_title_blocking_non_matching_headline_not_promoted(_stub_chain):", "    \"\"\"A near-but-not-equal headline must not promote (precision guard).\"\"\"", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _unique_with_candidates([_candidate(cand_id)])", "    _stub_chain[\"titles_by_article\"] = {", "        cand_id: (", "            \"A completely different story about local elections today\",", "            \"https://otherwire.com/x\",", "        )", "    }", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(headline=_VERBATIM_HEADLINE, url=\"https://example.com/incoming\"),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.best_match is None", "", "", "async def test_title_blocking_kill_switch_no_promotion(_stub_chain):", "    \"\"\"DEDUP_TITLE_BLOCKING_ENABLED=False \u2192 parity with pre-change (no promotion).\"\"\"", "    _stub_chain[\"config\"].DEDUP_TITLE_BLOCKING_ENABLED = False", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _unique_with_candidates([_candidate(cand_id)])", "    _stub_chain[\"titles_by_article\"] = {cand_id: (_VERBATIM_HEADLINE, \"https://otherwire.com/x\")}", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(headline=_VERBATIM_HEADLINE, url=\"https://example.com/incoming\"),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.best_match is None", "    assert _stub_chain[\"verifier_calls\"] == []", "", "", "async def test_title_blocking_promotion_still_corrected_by_time_window_demote(_stub_chain):", "    \"\"\"Ordering guard: a title-blocking promotion whose match sits outside the", "    \u00b1window is still demoted to UNIQUE by the downstream time-window step.", "    \"\"\"", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _unique_with_candidates([_candidate(cand_id)])", "    _stub_chain[\"titles_by_article\"] = {cand_id: (_VERBATIM_HEADLINE, \"https://otherwire.com/x\")}", "    # Matched article published a year out \u2014 outside \u00b1DEDUP_TIME_WINDOW_DAYS.", "    _stub_chain[\"matched_published_at\"] = _INCOMING_DATE - timedelta(days=365)", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(headline=_VERBATIM_HEADLINE, url=\"https://example.com/incoming\"),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.best_match is None", "    assert plan.match_info == {}", "", "", "async def test_syndication_signal_promotion_still_corrected_by_time_window_demote(_stub_chain):", "    \"\"\"Ordering guard for the absolute-count path: a signal promotion whose match", "    sits outside the \u00b1window is still demoted to UNIQUE downstream, and the", "    matched lineage is cleared before group resolution.", "    \"\"\"", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _syndication_signal_result(cand_id)", "    # Matched article published a year out \u2014 outside \u00b1DEDUP_TIME_WINDOW_DAYS.", "    _stub_chain[\"matched_published_at\"] = _INCOMING_DATE - timedelta(days=365)", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.best_match is None", "    assert plan.match_info == {}", "    assert _stub_chain[\"resolve_group_calls\"][0][\"best_match_article_id\"] is None", "", "", "async def test_syndication_signal_promotion_survives_in_window_match(_stub_chain):", "    \"\"\"Positive control for the ordering guard: inside the \u00b1window the signal", "    promotion survives the chain with its payload intact.", "    \"\"\"", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _syndication_signal_result(cand_id)", "    _stub_chain[\"matched_published_at\"] = _INCOMING_DATE - timedelta(days=3)", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert plan.best_match is not None", "    assert plan.best_match.article_id == cand_id", "    assert plan.match_info[\"syndication_signal\"][\"matched_article_id\"] == str(cand_id)", "    assert _stub_chain[\"resolve_group_calls\"][0][\"best_match_article_id\"] == cand_id", "", "", "async def test_syndication_signal_retarget_persists_matched_candidate_score(_stub_chain):", "    \"\"\"The persisted ``similarity_score`` describes the article ``best_match``", "    points at, not the higher-scored candidate ``article_score`` describes.", "", "    Without this the stored row would claim the top candidate's similarity while", "    ``matched_article_id`` named a different, lower-scoring article.", "    \"\"\"", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _syndication_signal_result(", "        cand_id, article_score=0.099, matched_article_score=0.062", "    )", "    _stub_chain[\"matched_published_at\"] = _INCOMING_DATE - timedelta(days=3)", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert plan.best_match.article_id == cand_id", "    assert plan.similarity_score == pytest.approx(0.062)", "    # The top-candidate score stays recoverable from the audit payload.", "    assert plan.match_info[\"syndication_signal\"][\"top_candidate_article_score\"] == pytest.approx(", "        0.099", "    )", "", "", "async def test_no_retarget_persists_top_candidate_score(_stub_chain):", "    \"\"\"Parity guard: with no retarget, ``similarity_score`` is unchanged from", "    ``article_score`` \u2014 the fix must not shift the ordinary score-based path.", "    \"\"\"", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _dedup_result(", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        article_score=0.83,", "        matched_article_id=cand_id,", "    )", "    _stub_chain[\"matched_published_at\"] = _INCOMING_DATE - timedelta(days=2)", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert plan.similarity_score == 0.83", "", "", "async def test_title_blocking_promotion_persists_no_similarity_score(_stub_chain):", "    \"\"\"A surviving headline-blocking promotion persists ``similarity_score`` None.", "", "    The promotion matches on verbatim-title identity, not on the diluted coverage", "    score (0.55 here), which describes the top ANN candidate \u2014 a possibly", "    different article than ``best_match`` now points at. Persisting that score", "    would make the stored row's similarity describe the wrong article; None is the", "    honest value, with provenance kept in ``match_info['title_blocking_key']``.", "    \"\"\"", "    cand_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _unique_with_candidates([_candidate(cand_id)])", "    _stub_chain[\"titles_by_article\"] = {cand_id: (_VERBATIM_HEADLINE, \"https://otherwire.com/x\")}", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(headline=_VERBATIM_HEADLINE, url=\"https://example.com/incoming\"),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert plan.best_match is not None", "    assert plan.best_match.article_id == cand_id", "    # The diluted composite score is NOT leaked as the match similarity...", "    assert plan.similarity_score is None", "    assert _stub_chain[\"dedup_result\"].article_score == 0.55", "    # ...but the promotion provenance stays recoverable.", "    assert plan.match_info[\"title_blocking_key\"][\"matched_article_id\"] == str(cand_id)", "", "", "# ---------------------------------------------------------------------------", "# rejected_match_info \u2014 the verifier adjudication that survives a UNIQUE outcome", "# ---------------------------------------------------------------------------", "#", "# The channel is populated for EVERY UNIQUE outcome that carried a verifier", "# addendum, not only for a same-publisher demote. The interaction matrix:", "#", "# | Path to UNIQUE                            | Addendum shape                  | rejected_match_info |", "# |-------------------------------------------|---------------------------------|---------------------|", "# | Same-publisher demote applied             | success keys                    | populated           |", "# | Verdict `different` / `inconclusive`      | success keys                    | populated           |", "# | NEAR_SYND verifier failure                | llm_failed / llm_band / reason  | populated           |", "# | No-context skip                           | llm_failed / llm_band / reason  | populated           |", "# | Verbatim skip, then time-window demote    | success keys incl. the skip     | populated           |", "# | UNIQUE with no verifier addendum          | none                            | None                |", "# | Verbatim skip, join kept                  | success keys                    | None                |", "", "_SUCCESS_ADDENDUM = {", "    \"llm_verdict\": {\"event\": \"same\", \"verbatim\": False, \"reason\": \"serial wire release\"},", "    \"llm_model\": \"gpt-test\",", "    \"llm_band\": \"mid_band\",", "    \"same_publisher\": {", "        \"incoming_publisher\": \"example.com\",", "        \"matched_publisher\": \"example.com\",", "        \"is_same_publisher\": True,", "        \"eligible\": True,", "        \"verbatim_skipped\": False,", "        \"enforced\": True,", "    },", "}", "", "_VERBATIM_SKIP_ADDENDUM = {", "    \"llm_verdict\": {\"event\": \"same\", \"verbatim\": True, \"reason\": \"identical body text\"},", "    \"llm_model\": \"gpt-test\",", "    \"llm_band\": \"mid_band\",", "    \"same_publisher\": {", "        \"incoming_publisher\": \"example.com\",", "        \"matched_publisher\": \"example.com\",", "        \"is_same_publisher\": True,", "        \"eligible\": False,", "        \"verbatim_skipped\": True,", "        \"enforced\": True,", "    },", "}", "", "_FAILURE_ADDENDUM = {", "    \"llm_failed\": True,", "    \"llm_band\": \"syndication_unique\",", "    \"reason\": \"RuntimeError('llm exploded')\",", "    \"same_publisher\": {", "        \"incoming_publisher\": \"example.com\",", "        \"matched_publisher\": \"example.com\",", "        \"is_same_publisher\": True,", "    },", "}", "", "_NO_CONTEXT_ADDENDUM = {", "    \"llm_failed\": True,", "    \"llm_band\": \"syndication_unique\",", "    \"reason\": \"matched_article_has_no_zyte_article\",", "}", "", "", "def _assert_carries_no_lineage(rejected):", "    \"\"\"A UNIQUE row must not gain match lineage it cannot honour.\"\"\"", "    assert \"matched_article_id\" not in rejected", "    assert \"best_match\" not in rejected", "    assert \"matched_chunk_index\" not in rejected", "", "", "@pytest.mark.parametrize(", "    \"addendum,expected_keys\",", "    [", "        pytest.param(", "            _SUCCESS_ADDENDUM,", "            {\"llm_verdict\", \"llm_model\", \"llm_band\", \"same_publisher\"},", "            id=\"same_publisher_demote_applied\",", "        ),", "        pytest.param(", "            {", "                \"llm_verdict\": {\"event\": \"different\", \"verbatim\": None, \"reason\": \"distinct\"},", "                \"llm_model\": \"gpt-test\",", "                \"llm_band\": \"mid_band\",", "                \"same_publisher\": _SUCCESS_ADDENDUM[\"same_publisher\"],", "            },", "            {\"llm_verdict\", \"llm_model\", \"llm_band\", \"same_publisher\"},", "            id=\"verdict_different\",", "        ),", "        pytest.param(", "            _FAILURE_ADDENDUM,", "            {\"llm_failed\", \"llm_band\", \"reason\", \"same_publisher\"},", "            id=\"verifier_failure\",", "        ),", "        pytest.param(", "            _NO_CONTEXT_ADDENDUM,", "            {\"llm_failed\", \"llm_band\", \"reason\"},", "            id=\"no_context_skip\",", "        ),", "    ],", ")", "async def test_unique_outcome_carries_its_verifier_adjudication(", "    _stub_chain, addendum, expected_keys", "):", "    \"\"\"Every UNIQUE outcome that reached a verifier addendum carries it forward.", "", "    ``match_info`` is still cleared \u2014 it describes a match that was KEPT, and there", "    is none. The adjudication travels on its own channel instead, so \"what this", "    article almost matched and why it was rejected\" is answerable in SQL rather than", "    only from a log line inside its retention window. The failure and no-context", "    rows matter as much as the demote row: those addenda carry ``llm_failed`` and", "    ``reason`` and nothing else, so a filter scoped to the success keys would drop", "    them silently.", "    \"\"\"", "    matched_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _dedup_result(", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        article_score=0.85,", "        matched_article_id=matched_id,", "    )", "    _stub_chain[\"verifier_impl\"] = lambda kw: (DeduplicationClassification.UNIQUE, addendum)", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.match_info == {}", "    assert plan.best_match is None", "    assert plan.rejected_match_info is not None", "    assert set(plan.rejected_match_info) == expected_keys", "    _assert_carries_no_lineage(plan.rejected_match_info)", "", "", "async def test_verbatim_skip_then_time_window_demote_still_carries_the_adjudication(_stub_chain):", "    \"\"\"The regression the hoisted capture exists for.", "", "    The verbatim gate rescues the pair at step 4, so the verifier branch never", "    clears anything \u2014 and then step 5's time-window demote turns it UNIQUE anyway.", "    A capture written inside the verifier branch would be skipped entirely on this", "    path, and the demote that actually fired would persist as an article that", "    matched nothing.", "    \"\"\"", "    matched_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _dedup_result(", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        article_score=0.85,", "        matched_article_id=matched_id,", "    )", "    # Verifier keeps the join (the verbatim skip), so only step 5 can demote it.", "    _stub_chain[\"verifier_impl\"] = lambda kw: (", "        DeduplicationClassification.SYNDICATION_CANDIDATE,", "        _VERBATIM_SKIP_ADDENDUM,", "    )", "    # Matched article published well outside DEDUP_TIME_WINDOW_DAYS of the incoming.", "    _stub_chain[\"matched_published_at\"] = _INCOMING_DATE + timedelta(days=30)", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.match_info == {}", "    assert plan.rejected_match_info is not None", "    assert plan.rejected_match_info[\"same_publisher\"][\"verbatim_skipped\"] is True", "    _assert_carries_no_lineage(plan.rejected_match_info)", "", "", "async def test_verbatim_skip_that_keeps_its_join_carries_no_rejected_adjudication(_stub_chain):", "    \"\"\"A kept join is not a rejection.", "", "    The pair stays SYNDICATION_CANDIDATE, so ``match_info`` keeps the whole addendum", "    on the join path and the rejected channel stays empty. If both were populated, a", "    query counting rejections would count kept joins too.", "    \"\"\"", "    matched_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _dedup_result(", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        article_score=0.85,", "        matched_article_id=matched_id,", "    )", "    _stub_chain[\"verifier_impl\"] = lambda kw: (", "        DeduplicationClassification.SYNDICATION_CANDIDATE,", "        _VERBATIM_SKIP_ADDENDUM,", "    )", "    _stub_chain[\"matched_published_at\"] = _INCOMING_DATE + timedelta(days=1)", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.SYNDICATION_CANDIDATE", "    assert plan.rejected_match_info is None", "    assert plan.match_info[\"same_publisher\"][\"verbatim_skipped\"] is True", "", "", "async def test_unique_without_a_verifier_addendum_carries_nothing(_stub_chain):", "    \"\"\"An article that simply matched nothing keeps the channel empty.", "", "    This is the noise guard: only a verifier rejection may populate it, so the most", "    common row type keeps ``match_info`` NULL exactly as it does today.", "    \"\"\"", "    _stub_chain[\"dedup_result\"] = _dedup_result(", "        classification=DeduplicationClassification.UNIQUE,", "        article_score=0.40,", "    )", "", "    plan = await _run(", "        _stub_chain,", "        article=_make_article(),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "    )", "", "    assert plan.classification == DeduplicationClassification.UNIQUE", "    assert plan.rejected_match_info is None", "", "", "async def test_load_earliest_titles_issues_single_batched_query():", "    \"\"\"Codex F5: N candidate ids \u2192 exactly ONE title query, not N.\"\"\"", "    from microservices.web_extraction.services.helpers.layer_two_classification import (", "        _load_earliest_titles_by_article,", "    )", "", "    ids = [uuid4() for _ in range(4)]", "    db = AsyncMock()", "    result_obj = MagicMock()", "    result_obj.all.return_value = [", "        (ids[0], \"title-0\", \"https://a.com/0\"),", "        (ids[1], \"title-1\", \"https://b.com/1\"),", "    ]", "    db.execute.return_value = result_obj", "", "    out = await _load_earliest_titles_by_article(db, ids)", "", "    assert db.execute.call_count == 1", "    assert out == {", "        ids[0]: (\"title-0\", \"https://a.com/0\"),", "        ids[1]: (\"title-1\", \"https://b.com/1\"),", "    }", "", "", "async def test_load_earliest_titles_empty_ids_skips_query():", "    \"\"\"No candidate ids \u2192 no query issued, empty map returned.\"\"\"", "    from microservices.web_extraction.services.helpers.layer_two_classification import (", "        _load_earliest_titles_by_article,", "    )", "", "    db = AsyncMock()", "    out = await _load_earliest_titles_by_article(db, [])", "    assert out == {}", "    db.execute.assert_not_called()", "", "", "# ---------------------------------------------------------------------------", "# Verifier OpenAI key", "# ---------------------------------------------------------------------------", "", "_VERIFIER_KEY = \"sk-sentinel-webex\"", "", "", "async def test_verifier_request_carries_the_key_passed_to_classification(_stub_chain, monkeypatch):", "    \"\"\"The key given to ``classify_layer_two_article`` reaches the verifier's llm-chat body.", "", "    Runs the real verifier chain down to the HTTP double, so the body also keeps", "    its ``failover_model``.", "    \"\"\"", "    matched_id = uuid4()", "    _stub_chain[\"dedup_result\"] = _dedup_result(", "        classification=DeduplicationClassification.SYNDICATION_CANDIDATE,", "        # Inside the syndication band, so the verifier runs.", "        article_score=borderline_verifier.web_config.DEDUP_SYNDICATION_THRESHOLD,", "        matched_article_id=matched_id,", "    )", "    _stub_chain[\"matched_published_at\"] = _INCOMING_DATE", "    monkeypatch.setattr(", "        layer_two_classification_module,", "        \"maybe_verify_borderline\",", "        borderline_verifier.maybe_verify_borderline,", "    )", "    monkeypatch.setattr(borderline_verifier.web_config, \"DEDUP_VERIFIER_ENABLED\", True)", "    monkeypatch.setattr(", "        borderline_verifier,", "        \"_load_matched_context\",", "        AsyncMock(", "            return_value={", "                \"title\": \"Matched article\",", "                \"lede\": \"Matched lede\",", "                \"published_at\": None,", "                \"publisher\": \"matched.example.org\",", "            }", "        ),", "    )", "    api_helper = APIHelperDouble(", "        default_response={", "            \"choices\": [", "                {\"content\": json.dumps({\"event\": \"same\", \"verbatim\": False, \"reason\": \"wire\"})}", "            ],", "            \"processed_via_failover\": False,", "        }", "    )", "", "    await classify_layer_two_article(", "        AsyncMock(),", "        api_helper,  # type: ignore[arg-type]", "        article=_make_article(),", "        article_markdown=\"body\",", "        chunk_vectors=_make_chunk_vectors(),", "        activity_id=uuid4(),", "        response_id=uuid4(),", "        retry_context=_retry_context_first_attempt(),", "        api_key=_VERIFIER_KEY,", "    )", "", "    assert len(api_helper.calls) == 1", "    body = api_helper.last_call().kwargs[\"body\"]", "    assert body[\"api_key\"] == _VERIFIER_KEY", "    assert body[\"failover_model\"] == borderline_verifier.web_config.LLM_CHAT_FAILOVER_MODEL.value", "    assert body[\"chat_model\"] == borderline_verifier._VERIFIER_PARAMS.default_chat_model.value", "", "", "def test_verifier_primary_model_is_an_openai_model():", "    \"\"\"The verifier sends web extraction's OpenAI key, so its primary must be an OpenAI model.", "", "    A Claude primary would need a provider guard before the key is sent.", "    \"\"\"", "    assert (", "        llm_model_provider(borderline_verifier._VERIFIER_PARAMS.default_chat_model)", "        is OPENAI_PROVIDER", "    )"], "blocks": [{"start": 1, "end": 61, "label": "Imports and module setup"}, {"start": 62, "end": 86, "label": "def _make_article"}, {"start": 87, "end": 99, "label": "def _make_chunk_vectors"}, {"start": 100, "end": 105, "label": "def _make_best_match_chunk"}, {"start": 106, "end": 123, "label": "def _dedup_result"}, {"start": 124, "end": 132, "label": "def _candidate"}, {"start": 133, "end": 143, "label": "def _unique_with_candidates"}, {"start": 144, "end": 181, "label": "def _syndication_signal_result"}, {"start": 182, "end": 278, "label": "def _stub_chain"}, {"start": 279, "end": 287, "label": "def _run"}, {"start": 288, "end": 296, "label": "def _retry_context_first_attempt"}, {"start": 297, "end": 353, "label": "def test_demote_fires_when_matched_is_outside_window"}, {"start": 354, "end": 377, "label": "def test_demote_skipped_when_matched_is_inside_window"}, {"start": 378, "end": 402, "label": "def test_window_boundary_inclusive"}, {"start": 403, "end": 429, "label": "def test_duplicate_is_exempt_from_demote"}, {"start": 430, "end": 454, "label": "def test_demote_skipped_when_matched_has_no_published_date"}, {"start": 455, "end": 479, "label": "def test_demote_skipped_when_incoming_has_no_published_date"}, {"start": 480, "end": 510, "label": "def test_demote_disabled_when_window_days_is_zero"}, {"start": 511, "end": 545, "label": "def test_title_blocking_promotes_cross_publisher_verbatim_headline"}, {"start": 546, "end": 572, "label": "def test_title_blocking_verifier_rejection_demotes_to_unique"}, {"start": 573, "end": 597, "label": "def test_title_blocking_verifier_failure_biases_unique"}, {"start": 598, "end": 625, "label": "def test_title_blocking_verifier_confirmation_keeps_promotion"}, {"start": 626, "end": 647, "label": "def test_title_blocking_same_publisher_not_promoted"}, {"start": 648, "end": 676, "label": "def test_title_blocking_subdomain_same_publisher_not_promoted"}, {"start": 677, "end": 705, "label": "def test_title_blocking_sibling_subdomains_same_publisher_not_promoted"}, {"start": 706, "end": 733, "label": "def test_title_blocking_two_label_suffix_publishers_still_cross_publisher"}, {"start": 734, "end": 756, "label": "def test_registrable_domain_reduction"}, {"start": 757, "end": 776, "label": "def test_title_blocking_short_masthead_not_promoted"}, {"start": 777, "end": 805, "label": "def test_title_blocking_deterministic_winner_highest_similarity"}, {"start": 806, "end": 834, "label": "def test_title_blocking_deterministic_winner_tiebreak_smallest_uuid"}, {"start": 835, "end": 859, "label": "def test_title_blocking_non_matching_headline_not_promoted"}, {"start": 860, "end": 881, "label": "def test_title_blocking_kill_switch_no_promotion"}, {"start": 882, "end": 906, "label": "def test_title_blocking_promotion_still_corrected_by_time_window_demote"}, {"start": 907, "end": 932, "label": "def test_syndication_signal_promotion_still_corrected_by_time_window_demote"}, {"start": 933, "end": 957, "label": "def test_syndication_signal_promotion_survives_in_window_match"}, {"start": 958, "end": 989, "label": "def test_syndication_signal_retarget_persists_matched_candidate_score"}, {"start": 990, "end": 1015, "label": "def test_no_retarget_persists_top_candidate_score"}, {"start": 1016, "end": 1111, "label": "def test_title_blocking_promotion_persists_no_similarity_score"}, {"start": 1112, "end": 1118, "label": "def _assert_carries_no_lineage"}, {"start": 1119, "end": 1187, "label": "def test_unique_outcome_carries_its_verifier_adjudication"}, {"start": 1188, "end": 1227, "label": "def test_verbatim_skip_then_time_window_demote_still_carries_the_adjudication"}, {"start": 1228, "end": 1261, "label": "def test_verbatim_skip_that_keeps_its_join_carries_no_rejected_adjudication"}, {"start": 1262, "end": 1286, "label": "def test_unique_without_a_verifier_addendum_carries_nothing"}, {"start": 1287, "end": 1310, "label": "def test_load_earliest_titles_issues_single_batched_query"}, {"start": 1311, "end": 1329, "label": "def test_load_earliest_titles_empty_ids_skips_query"}, {"start": 1330, "end": 1389, "label": "def test_verifier_request_carries_the_key_passed_to_classification"}, {"start": 1390, "end": 1398, "label": "def test_verifier_primary_model_is_an_openai_model"}], "lineCount": 1398, "sha256": "04c0c4933fc029a690060cf9aa504cdadab3ab252800bc97e6addcdb9fde0af7", "endsWithNewline": true});
